// Scenarios pinned against FL's real FL Keys plugin (test host, 16-sample blocks) on the synthetic wavetables of
// flkeys-syn.ts. The golden numbers (flkeys.golden.ts) are generated by .flref/flkeys with `writeGolden`.
import type { SynName } from './flkeys-syn';

export interface Note { key: number; vel?: number; start: number; len: number; pan?: number; fine?: number }
export interface Scenario {
  table: SynName;
  params?: number[];
  notes: Note[];
  sr?: number;
  /** Channel knobs (host: --chan-vol / --chan-pan / --chan-pitch / --root-note), steps by sample position (multiples of 128). */
  vol?: number; pan?: number; pitch?: number; root?: number;
  at?: { frame: number; vol?: number; pan?: number; pitch?: number }[];
  tail?: number;
  /** Looser comparison (the table is converted by the engine; FL's resampler is not reproduced exactly). */
  loose?: boolean;
}

export const DEFAULT_PARAMS = [0, 0, 0, -1000, 784, 502, -248, 1000, 0, 123, 0, 0, 0, 0, 0];
export const BUSY_PARAMS = [150, -200, 350, -400, 500, 700, 100, 1400, 300, 300, 200, 500, -300, 40000, 450];

const n = (key: number, vel: number, start: number, len: number, o: Partial<Note> = {}): Note => ({ key, vel, start, len, ...o });

/** The parameters stored in FL's render test project (Grand Piano with its descriptor's Decay / Release / Stereo). */
export const RENDER_TEST_PARAMS = [-1000, -164, 0, -1000, 784, 502, -248, 0, 0, 123, 0, 0, 0, 0, 0];
export const RENDER_TEST_NOTES: Note[] = [24, 36, 48, 60, 72, 84, 96].map((key, i) => ({ key, vel: 64, start: i * 0.25, len: 0.25 }));

